"""Generate docs/results/paid_models_summary.md: tables of the paid-model experiment (A baseline vs B with failure output, Python 61 / Java 59 / Java 257 cases), the A->B improvements,
the cost analysis and the outcome, all computed from the scored results and the request logs. Run: PYTHONPATH=. python scripts/thesis_analysis/paid_models_summary_md.py > docs/results/paid_models_summary.md"""
import contextlib, io, json
from pathlib import Path
src = open(Path(__file__).with_name("paid_models_report.py")).read()
g = {"__name__": "paid_report"}
with contextlib.redirect_stdout(io.StringIO()):
    exec(compile(src, "paid_models_report", "exec"), g)
PAID, jcols, pcols, ids59, valid257, ids61, rates = g["PAID"], g["jcols"], g["pcols"], g["ids59"], g["valid257"], g["ids61"], g["rates"]
jgroup, jw, pgroup, pw, P = g["jgroup"], g["jw"], g["pgroup"], g["pw"], g["P"]
PRICE = {"qn": (0.12, 0.80), "q3c": (0.30, 1.00), "dev": (0.40, 2.00), "glm": (0.07, 1.40), "kimi": (0.50, 2.50)}
REF = [("Qwen3-Coder-30B (local, vLLM)", "qwen3-coder-30b (local)", None), ("particle-1 (free, OpenRouter)", "particle-1 (free)", None)]
MODELS = [(n, n, s) for n, s in PAID]
def reqs(run):
    f = P / run / "requests.jsonl"
    return [json.loads(l) for l in open(f)] if f.exists() else []
def cost_of(run, subset=None):
    r = [x for x in reqs(run) if subset is None or x["id"] in subset]
    return sum(x.get("cost_reported", 0) or 0 for x in r), sum(x.get("tokens_in", 0) or 0 for x in r), sum(x.get("completion_tokens", 0) or 0 for x in r), len({x["id"] for x in r})
pids = {"java": set(json.load(open(P / "ids_java59.json"))), "py": set(json.load(open(P / "ids_python61.json")))}
def row(cols, name, ids, group, w):
    a, b = cols.get(name + " A", {}), cols.get(name + " B", {})
    sa = [i for i in ids if i in a]; sb = [i for i in ids if i in b]
    if not sb: return None
    both = [i for i in sb if i in a]
    wa = rates(both, lambda i: a[i][1], group, w); wb = rates(both, lambda i: b[i][1], group, w)
    return {"A": wa[2], "B": wb[2], "d": wb[2] - wa[2], "plus": sum(1 for i in both if b[i][1] and not a[i][1]), "minus": sum(1 for i in both if a[i][1] and not b[i][1]),
            "solved": wb[0], "unsolved": wb[1], "empty": sum(1 for i in sb if not b[i][0]), "pass": sum(b[i][1] for i in sb), "n": len(sb)}
SETS = [("Python, 61 cases", pcols, ids61, pgroup, pw, "py"), ("Java, the 59 cases of the agent comparison", jcols, ids59, jgroup, jw, "java"), ("Java, all 257 cases whose reference passes here", jcols, valid257, jgroup, jw, "java257")]
out = []
p = out.append
p("# Paid and free LLMs with and without the failure output: results, improvements, cost and outcome\n")
p("*Generated by `scripts/thesis_analysis/paid_models_summary_md.py` from the scored results (`~/eval_paid*`, `~/eval_java_plaus`) and the request logs; written 2026-11-21.*\n")
p("## 1. Set-up\n")
p("- **Question:** how much does adding the failure output of the broken test (variant **B**) improve test repair compared with the baseline prompt (**A**), and which affordable models do best?")
p("- **Prompt (all runs):** the test function, the broken lines (the lines the reference repair changes), up to 4 source hunks. B adds the cleaned failure output of the broken test (pytest output for Python, Maven output of the broken run for Java, at most 2500 characters).")
p("- **Models:** Qwen3-Coder-Next, Qwen3-Coder (large), Devstral-2512, GLM-5.3 and Kimi-K2.5 on OpenRouter (paid, at most 8192 output tokens, empty answers retried at 16384; GLM and Kimi with reasoning effort low); the free particle-1 and the local Qwen3-Coder-30B (vLLM) as references.")
p("- **Cases:** Python 61 and Java 59 (the cases of the agent comparison), and for the four cheaper models also all 257 Java cases whose reference passes in our environment (Kimi only on the 61 / 59 cases). One candidate per case at temperature 0.7.")
p("- **Metric:** checked plausible@1 (the test passes AND the test needs the repaired lines OR the candidate still asserts), weighted with the population sizes of the contrast subsets (about 60 cases: roughly +-7 points per group). Gain = B minus A; paired = cases gained / lost on the same cases.")
p("- **Agent for comparison:** mini-SWE-agent with Qwen3-Coder-30B (local, offline sandbox, 80 calls, no marked broken lines): Python 48.3% (61 cases), Java 63.4% strict / 70.3% relaxed (59 cases).\n")
p("## 2. Results\n")
names = [(n, key) for n, key, _ in MODELS] + [(n, key) for n, key, _ in REF]
for title, cols, ids, group, w, tag in SETS:
    p(f"### {title}\n")
    p("| Model | A (baseline) | B (+ failure output) | Gain B-A | Paired +/- | B: solved / unsolved group | Empty (B) |")
    p("|---|---|---|---|---|---|---|")
    rows = []
    for label, key in names:
        r = row(cols, key if key != label else label, ids, group, w)
        if r: rows.append((label, r))
    for label, r in rows:
        if r["n"] != len(ids): label = f"{label} (only {r['n']} cases)"
        p(f"| {label} | {r['A']:.1f}% | {r['B']:.1f}% | {r['d']:+.1f} | +{r['plus']} / -{r['minus']} | {r['solved']:.1f}% / {r['unsolved']:.1f}% | {r['empty']} |")
    p("")
p("## 3. Improvement from the failure output (B minus A, weighted points)\n")
p("| Model | Python 61 | Java 59 | Java 257 |")
p("|---|---|---|---|")
imp = {}
for label, key in names:
    cells = []
    for title, cols, ids, group, w, tag in SETS:
        r = row(cols, key if key != label else label, ids, group, w)
        cells.append((f"{r['d']:+.1f} (+{r['plus']}/-{r['minus']})" + (f" [only {r['n']} cases]" if r["n"] != len(ids) else "")) if r else "-")
        imp[(label, tag)] = r["d"] if r else None
    p(f"| {label} | " + " | ".join(cells) + " |")
p("\nEvery model improves with the failure output on every set except the local Qwen3-Coder-30B on the 59 Java cases (-1.2, within noise). The gain is larger on Python (+10 to +31) than on Java (+6 to +21 on 59 cases, +6 to +12 on 257), and largest for the models that start from a low baseline or that reason longer (Kimi, particle-1).\n")
p("## 4. Cost analysis\n")
p(f"- **Total spend:** 7.87 USD of the 10 USD credit (logs 7.852 + trial 0.013 = 7.865; account 7.866). Kimi-K2.5 took 5.58 USD; the other four models together 2.27 USD for their full runs.")
p("- **Why Kimi is expensive:** its reasoning writes 8.7k-12.9k output tokens per answer (2.2M of the 2.5M completion tokens of the whole experiment), the other paid models 40-270.\n")
p("| Model | Price in / out (USD per 1M) | Spend on its runs | Cost per case (B) Python / Java | Output tokens per answer (B) Python / Java | USD per plausible repair (B) Python 61 / Java 59 |")
p("|---|---|---|---|---|---|")
for name, short in PAID:
    allc = sum(cost_of(f"{short}_{l}{v}")[0] for l in ("java", "py") for v in "AB")
    cp = cost_of(f"{short}_pyB", None); cj = cost_of(f"{short}_javaB", None)
    spy = cost_of(f"{short}_pyB", pids["py"]); sjv = cost_of(f"{short}_javaB", pids["java"])
    rp, rj = row(pcols, name, ids61, pgroup, pw), row(jcols, name, ids59, jgroup, jw)
    perrep = lambda s, r: f"{s[0] / r['pass']:.4f}" if r and r["pass"] else "-"
    p(f"| {name} | {PRICE[short][0]:.2f} / {PRICE[short][1]:.2f} | {allc:.2f} USD | {cp[0]/max(cp[3],1):.4f} / {cj[0]/max(cj[3],1):.4f} | {cp[2]/max(cp[3],1):.0f} / {cj[2]/max(cj[3],1):.0f} | {perrep(spy, rp)} / {perrep(sjv, rj)} |")
p("| particle-1 (free) | free | 0 | 0 / 0 | about 1500-2600 | 0 / 0 |")
p("| Qwen3-Coder-30B (local) | GPU only | 0 | - | about 40-60 | - |")
p("")
p("- **Whole comparison on the 59 Java + 61 Python cases (A and B):** " + "; ".join(f"{n} {sum(cost_of(f'{s}_{l}{v}', pids[l])[0] for l in ('java','py') for v in 'AB'):.2f}" for n, s in PAID) + " USD.")
p("- **Per 1000 cases (B):** Qwen3-Coder about 0.3-0.5 USD, Devstral 0.4-0.7, GLM-5.3 0.7-1.3, Kimi 16-22 USD.")
p("- **Estimates vs actual:** Kimi cost about twice my estimate (longer reasoning), GLM about five times less (very short answers at low effort).\n")
p("## 5. Outcome\n")
bj = {n: row(jcols, n, valid257, jgroup, jw) for n, _ in PAID if row(jcols, n, valid257, jgroup, jw)}
p("1. **The failure output is the single most valuable addition to the prompt.** It improves all seven prompt-only models on Python (+9.5 to +31 points) and nearly all on Java (+6 to +21), at a cost of 160-400 extra tokens. Definitions of the changed symbols added nothing (earlier ablation).")
p("2. **Cheap code models with the failure output are close to the agent.** Qwen3-Coder (large) with B reaches 48.4% on Python (agent 48.3%) and 66.5% on the 59 Java cases (agent strict 63.4%, relaxed 70.3%) for about 0.0003-0.0005 USD per case.")
p("3. **Best prompt-only models:** Kimi-K2.5 (Python 60.3%, Java-59 72.2%) and the free particle-1 (58.2%, 73.0%; Java-257 73.5%) are level with each other. Excluding Kimi, particle-1 is the best model: paired against each other paid model on the same cases it wins clearly (for example Java-257: 45 vs 7 against Qwen3-Coder, 34 vs 8 against GLM-5.3, 50 vs 5 against Devstral).")
ratio = lambda kind: cost_of(f"kimi_{kind}")[0] / max(cost_of(f"kimi_{kind}")[3], 1) / (cost_of(f"q3c_{kind}")[0] / max(cost_of(f"q3c_{kind}")[3], 1))
p(f"4. **Cost-effectiveness:** Kimi costs {ratio('pyB'):.0f}-{ratio('javaB'):.0f} times more per case than Qwen3-Coder on the B runs ({ratio('pyA'):.0f}-{ratio('javaA'):.0f} times on the baseline runs; 16-35 times GLM-5.3, 33-66 times Devstral) for about 12 points more on Python; particle-1 gives the same accuracy for free but depends on free-tier availability and returns more empty answers (3-5 per run, counted as failures).")
p("5. **Interpretation caveat:** the two best models are also the two that think longest (1.5-12k tokens per answer); the other paid models wrote almost nothing at my settings, so part of the ranking may reflect thinking depth, not model quality. A run of GLM-5.3 with higher reasoning effort (about 0.7 USD) would test this.")
p("6. **Limits:** about 60 cases per comparison (+-7 points per group), one candidate at temperature 0.7, recent models may have seen these public repositories, and the agent (no marked broken lines, local 30B model) is not directly comparable with prompt-only runs that are told the exact lines.\n")
p("## 6. Where the data and scripts are\n")
p("- Runs: `~/eval_paid/<model>_<java|py><A|B>/` (predictions, `requests.jsonl` with tokens and cost per request); scored results: `~/eval_java_plaus/union.json` (Java), `~/eval_paid_plaus/` (Python).")
p("- Scripts: `paid_models_chain.sh` (generation with a spending guard), `paid_models_report.py` (tables), `paid_cost_report.py` (cost), `paid_models_summary_md.py` (this document). Related notes: `paid_models_results.txt`, `paid_models_cost.txt`, `agent_vs_no_agent_summary.txt`.")
print("\n".join(out))
